import re
import urllib.request
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(API_URL):
    """
    Get the public IP address of the current host from an API.
    The function should raise the exception for: If the API request fails, the function will return the error message.
    The function should output with:
        str: The public IP address.
    """
    try:
        with urllib.request.urlopen(API_URL) as response:
            data = response.read().decode('utf-8')
            ip_match = re.search(IP_REGEX, data)
            if ip_match:
                return ip_match.group(0)
            else:
                json_data = json.loads(data)
                if 'ip' in json_data:
                    return json_data['ip']
                else:
                    raise ValueError("IP address not found in the API response")
    except urllib.error.URLError as e:
        raise Exception(f"Failed to connect to the API: {e}")
    except json.JSONDecodeError:
        raise Exception("Failed to parse JSON response from API")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

