import json
from glob import glob
import os
def task_func(directory, string):
    """
    Search for a specific string within the JSON data of files in a given directory and its subdirectories.

    Args:
        directory (str): The directory path to search in.
        string (str): The string to search for (case-sensitive).

    Returns:
        list: A list of file paths (str) containing the string within their JSON data.
    """
    matching_files = []

    # Recursively find all JSON files in the directory and subdirectories
    json_files = []
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.json'):
                json_files.append(os.path.join(root, file))

    # Check each JSON file for the string
    for file_path in json_files:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                    # Recursively search through the JSON structure
                    def search_in_json(obj, target):
                        if isinstance(obj, dict):
                            for key, value in obj.items():
                                if key == target or search_in_json(value, target):
                                    return True
                        elif isinstance(obj, list):
                            for item in obj:
                                if search_in_json(item, target):
                                    return True
                        elif isinstance(obj, str):
                            return obj == target
                        return False

                    if search_in_json(data, string):
                        matching_files.append(file_path)
                except json.JSONDecodeError:
                    # Skip invalid JSON files
                    continue
        except (IOError, OSError):
            # Skip files that can't be read
            continue

    return matching_files

