import json
import re
import pandas as pd
def task_func(json_str):
    """
    Load a JSON string into a dictionary, normalize the dictionary by doubling the numerical values,
    and then create a Pandas DataFrame from the dictionary.

    Parameters:
    json_str (str): A JSON string representing a flat dictionary

    Returns:
    DataFrame: A pandas DataFrame created from the normalized dictionary
    """
    if not json_str or json_str.strip() == '':
        return pd.DataFrame()

    try:
        data_dict = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()

    if not isinstance(data_dict, dict):
        return pd.DataFrame()

    normalized_dict = {}

    for key, value in data_dict.items():
        if isinstance(value, (int, float)):
            # Double numerical values
            normalized_dict[key] = value * 2
        elif isinstance(value, list):
            # Process lists - double numerical values, leave others unchanged
            processed_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    processed_list.append(item * 2)
                elif isinstance(item, str):
                    # Try to extract numbers from strings using regex
                    numbers = re.findall(r'-?\d+\.?\d*', item)
                    if numbers:
                        # Convert first found number and double it
                        try:
                            num = float(numbers[0]) * 2
                            processed_list.append(num)
                        except ValueError:
                            processed_list.append(item)
                    else:
                        processed_list.append(item)
                else:
                    processed_list.append(item)
            normalized_dict[key] = processed_list
        elif isinstance(value, str):
            # Try to extract numbers from strings using regex
            numbers = re.findall(r'-?\d+\.?\d*', value)
            if numbers:
                # Convert first found number and double it
                try:
                    num = float(numbers[0]) * 2
                    normalized_dict[key] = num
                except ValueError:
                    normalized_dict[key] = value
            else:
                normalized_dict[key] = value
        else:
            # Leave non-numerical values unchanged
            normalized_dict[key] = value

    # Create DataFrame
    try:
        df = pd.DataFrame(normalized_dict)
    except ValueError:
        return pd.DataFrame()

    return df

