import json
import pandas as pd
import numpy as np
from collections import defaultdict
def task_func(input_file="data.json"):
    """
    Read a list of dictionaries from a JSON file, calculate the mean and median 
    for each key (ignoring non-numeric or missing values), and convert the results 
    into a Pandas DataFrame.

    Parameters:
    input_file (str): Path to the JSON file. Default is "data.json".

    Returns:
    pd.DataFrame: A DataFrame indexed and sorted by the variable names (keys) from the
                  input data, containing columns 'mean' and 'median'.
    """
    try:
        with open(input_file, 'r') as f:
            data = json.load(f)
    except FileNotFoundError:
        print(f"Error: File '{input_file}' not found.")
        return pd.DataFrame(columns=['mean', 'median'])
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON format in '{input_file}'.")
        return pd.DataFrame(columns=['mean', 'median'])

    if not isinstance(data, list):
        print("Error: JSON data should be a list of dictionaries.")
        return pd.DataFrame(columns=['mean', 'median'])

    # Collect all numeric values for each key
    values_by_key = defaultdict(list)

    for item in data:
        if not isinstance(item, dict):
            continue

        for key, value in item.items():
            # Check if value is numeric (int or float) and not None
            if isinstance(value, (int, float)) and value is not None:
                values_by_key[key].append(value)

    # Calculate mean and median for each key
    results = {}
    for key, values in values_by_key.items():
        if values:  # Only process keys with numeric values
            results[key] = {
                'mean': np.mean(values),
                'median': np.median(values)
            }

    # Create DataFrame and sort by index (keys)
    df = pd.DataFrame.from_dict(results, orient='index')
    df.index.name = 'variable'
    df = df.sort_index()

    return df

